mapper.select:
select r.*, c.name as course_name, co.name as coach_name from order_review r left join course c on r.course_id = c.id left join coach co on r.coach_id = co.id
and r.coach_id = #{coachId}
order by r.create_time desc

mapper.update:
update coach set rating =
    (select round(avg(coach_rating), 1) from order_review where coach_id = #{coachId})
where id = #{coachId}
